// ============================================================
// Nodo: Purgar conversaciones antiguas
// Elimina los archivos de conversaciones sin actividad (fecha de
// ultima modificacion) en mas de DIAS_RETENCION dias.
// Solo toca archivos .json dentro de las carpetas del historial.
// ============================================================

const fs = require('fs');
const path = require('path');

const DIAS_RETENCION = 30;
const LIMITE = Date.now() - DIAS_RETENCION * 24 * 60 * 60 * 1000;
const CARPETAS = [
  '/home/node/.n8n/historial',        // historial actual (carpeta por usuario)
  '/home/node/.n8n/conversaciones'    // formato anterior (archivo por navegador)
];

let revisados = 0;
let eliminados = 0;

function purgarArchivo(ruta) {
  const st = fs.lstatSync(ruta);
  if (!st.isFile() || !ruta.endsWith('.json')) return;
  revisados++;
  if (st.mtimeMs < LIMITE) {
    fs.unlinkSync(ruta);
    eliminados++;
  }
}

for (const raiz of CARPETAS) {
  if (!fs.existsSync(raiz)) continue;
  for (const nombre of fs.readdirSync(raiz)) {
    const ruta = path.join(raiz, nombre);
    const st = fs.lstatSync(ruta);
    if (st.isDirectory()) {
      for (const f of fs.readdirSync(ruta)) purgarArchivo(path.join(ruta, f));
      if (fs.readdirSync(ruta).length === 0) fs.rmdirSync(ruta);
    } else {
      purgarArchivo(ruta);
    }
  }
}

return [{
  json: {
    ejecutado: new Date().toISOString(),
    dias_retencion: DIAS_RETENCION,
    revisados: revisados,
    eliminados: eliminados
  }
}];
